@Component("branch-handler")
@ProcessingGroup("branch-processing-group")
public class BranchEventHandler {
	
	// core constructor
	BranchEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBranchEvent
     */
    @EventHandler
    public void handle( CreateBranchEvent event) {
        entityManager.persist(new Branch(event.getBranchId(), event.getName(), event.getBranchCode(), event.getAddress(), event.getPhone(), event.getOpeningHours(), event.getBank(), event.getAccounts(), event.getLoanAccounts(), event.getAtms()));
    }

    /*
     * @param	event UpdateBranchEvent
     */
    @EventHandler
    public Branch handle( UpdateBranchEvent event) {
    	entityManager.merge(new Branch(event.getBranchId(), event.getName(), event.getBranchCode(), event.getAddress(), event.getPhone(), event.getOpeningHours(), event.getBank(), event.getAccounts(), event.getLoanAccounts(), event.getAtms()));
    }
    
    /*
     * @param	event DeleteBranchEvent
     */
    @EventHandler
    public void on( DeleteBranchEvent event) {
    	Branch entity = new Branch();
   
    	// ------------------------------------------
    	// apply the BranchId
    	// ------------------------------------------
    	entity.setBranchId( event.getBranchId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BranchRepository branchEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BranchEventHandler.class.getName());

}
